using Hyper.Domain.Entities.Integrations; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; namespace Hyper.Infrastructure.Data.Configurations; public sealed class InventoryReservationLogConfiguration:IEntityTypeConfiguration<InventoryReservationLog>{public void Configure(EntityTypeBuilder<InventoryReservationLog>b){b.ToTable("InventoryReservationLogs");b.HasKey(x=>x.Id);b.Property(x=>x.ReservationKey).HasMaxLength(200).IsRequired();b.Property(x=>x.Source).HasMaxLength(50).IsRequired();b.HasIndex(x=>new{x.ShopId,x.ReservationKey}).IsUnique();}}
